---@class ParkourBoss
local ParkourBoss = Class("ParkourBoss")



function ParkourBoss:__init()
    self.showState = ParkourGameUtil.BossShowState.NotStart --0:未开始 1:倒计时 2:出现 
    self.state = ParkourGameUtil.BossState.Hide
    
    self.attackCD = 5
    self.attackTimer = 0
    self.appearCD = 3
    self.appearTimer = self.appearCD
    self.model = nil
    --self.pauseAppear = false -- 暂停倒计时
    self.attackItems = {}
    ---
    self.co_1 = nil
end


---@param crowData_ CrowData
function ParkourBoss:Init(crowData_,factory)

    self.model = self.controller.transform:Find('Model')
    CfUtils.SetActive(self.model.gameObject, false)
    self.maxHealth = ParkourGameUtil.Params.BossData.Hp
    self.health = self.maxHealth
    ---
    self.attackCD = 6--crowData.attackCD

    self.appearCD = crowData_.appearCD
    self.appearTimer = self.appearCD
    self.attackDatas = crowData_.attackDatas
    self.attackType = crowData_.firstAttackType -- 0:横向 1:纵向
    self.attackSpeed1 = crowData_.attackSpeed1
    self.attackSpeed2 = crowData_.attackSpeed2
    ---@type ParkourFactory
    self.factory = factory


    self.animator = self.model:GetComponent(typeof(Animator))
end


-- 无限模式下, 切换为新 map 中的 boss 数据;
function ParkourBoss:ChangeCrowData(crowData_)
    self.appearCD = crowData_.appearCD
    --self.appearTimer = self.appearCD
    self.attackDatas = crowData_.attackDatas
    --self.attackType = crowData_.firstAttackType -- 0:横向 1:纵向
    self.attackSpeed1 = crowData_.attackSpeed1
    self.attackSpeed2 = crowData_.attackSpeed2
end


function ParkourBoss:OnDestroy()
    CoStop(self.co_1)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- 由 ParkourGameRunner 调用
function ParkourBoss:Update()
    --self:_CheckState()

    if self.showState == ParkourGameUtil.BossShowState.CountDown then
        -- 隐身技能暂停 八哥出现倒计时
        -- if self.pauseAppear then
        --     return
        -- end
        self.appearTimer = self.appearTimer - Time.deltaTime
        if self.appearTimer < 0 then
            self.showState = ParkourGameUtil.BossShowState.Show
            self:_Appear()
            self.appearTimer = self.appearCD
        end
    elseif self.showState == ParkourGameUtil.BossShowState.Show then
        self:_SimpleAI()    
    end
    
    for i, v in pairs(self.attackItems) do
        if v.recycled == false then
            v:Tick(Time.deltaTime)
        else
            table.remove(self.attackItems,i)
        end
    end    
end


