function ParkourBoss:_Appear()
    --printError("--Boss:Appear")
    Mgr.scores.mynaFind = 1 -- 0:未发现,1:发现
    ---
    self.showState = ParkourGameUtil.BossShowState.Show
    Events.Broadcast(ParkourGameUtil.Events.BossCome)
    CfUtils.SetActive(self.model.gameObject, true) --TODO 飞进来的动画

    self:_PlayAnim( 0 )
    self.animator:Play( "idle", -1 ) -- 动画瞬切

    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "crow_appear_12001801" )
end

function ParkourBoss:_RunAway()

    Mgr.scores.bossRunAwayNums = Mgr.scores.bossRunAwayNums + 1

    --printError("--Boss:RunAway")
    self.showState = ParkourGameUtil.BossShowState.NotStart
    self.appearTimer = self.appearCD
    self.health = self.maxHealth
    Events.Broadcast(ParkourGameUtil.Events.BossLeave)
    CfUtils.SetActive(self.model.gameObject, false) --飞走


    CoStop(self.co_1)
    self.co_1 = CoStart(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 3 ))
        self:StartCountDown()
    end)

end

function ParkourBoss:OnHit()
    --printError("--Boss:OnHit")
    self.health = self.health - 1
    Events.Broadcast(ParkourGameUtil.Events.BossTakeDamage, self.health)
    --self:_PlayAnim( 3 )
    self.animator:Play( "hit", -1 )-- 动画瞬切
end

function ParkourBoss:Die()
    --printError("--Boss:Die")
end

function ParkourBoss:_Attack()
    --self:_RecycleAttackItems()
    self.attackType = self.attackType%2
    if self.attackType == 0 then
        --printError("--Boss: Attack 1")
        if #self.attackDatas.attackData1 > 0 then 
            local attackData = self.attackDatas.attackData1[math.random(1,#self.attackDatas.attackData1)]
            self:_AttackHorizontal(attackData,self.attackSpeed1,2.5)
            --self:_PlayAnim( 1 )
            self.animator:Play( "skill1", -1 )-- 动画瞬切
        end         
    else
        if #self.attackDatas.attackData2 > 0 then 
            --printError("--Boss: Attack 2")
            local attackData = self.attackDatas.attackData2[math.random(1,#self.attackDatas.attackData2)]
            self:_AttackVertical(attackData,self.attackSpeed2,2.5)
            --self:_PlayAnim( 2 )
            self.animator:Play( "skill2", -1 )-- 动画瞬切
        end 
    end
    self.attackType = self.attackType + 1
end

function ParkourBoss:_AttackHorizontal(attackData,speed,interVal)
    local startPos = Vector3(8,0,0)
    for i, v in ipairs(attackData) do
        for j = 1, v.objectsNum do
            local pos = startPos + Vector3((j-1) * interVal,v.pos,0)
            self:_CreateBulletFeather(pos,speed)
        end
    end
end

function ParkourBoss:_AttackVertical(attackData,speed,interVal)
    local startPos = Vector3(0,4.5,0)
    for i, v in ipairs(attackData) do
        for j = 1, v.objectsNum do
            local pos = startPos + Vector3(v.pos,(j-1) * interVal,0)
            self:_CreateBulletRock(pos,speed)
        end
    end
end

function ParkourBoss:_CreateBulletFeather(pos,speed)
    self.factory:GenerateTrackItem(AttackItemPath_feather,function(trackItem)
        ---@type BulletFeather
        local attackItem = trackItem
        attackItem:Init(pos,speed,self.controller.transform.parent)
        CfUtils.SetActive(attackItem.controller.transform.gameObject,true)
        table.insert(self.attackItems,attackItem)
    end)
end



function ParkourBoss:_CreateBulletRock(pos,speed)
    self.factory:GenerateTrackItem(AttackItemPath_rock,function(trackItem)
        ---@type BulletRock
        local attackItem = trackItem
        attackItem:Init(pos,speed,self.controller.transform.parent)
        CfUtils.SetActive(attackItem.controller.transform.gameObject,true)
        table.insert(self.attackItems,attackItem)
    end)
end



function ParkourBoss:_RecycleAttackItems()
    for i, v in ipairs(self.attackItems) do
        if v.recycled == false then
            v:Recycle()    
        end
    end
    self.attackItems = {}
end

function ParkourBoss:StartCountDown()
    --printError("--Boss:StartCountDown")
    self.showState = ParkourGameUtil.BossShowState.CountDown
    Events.Broadcast(ParkourGameUtil.Events.BossCountDownStart, self.appearCD)
end



function ParkourBoss:_SimpleAI()
    if self.health <=0 then
        self:_RunAway()
        return
    end

    -- 隐身技能暂停 八哥的攻击间隔
    -- if self.pauseAppear then
    --     return
    -- end

    self.attackTimer = self.attackTimer - Time.deltaTime
    if self.attackTimer < 0 then
        self:_Attack()
        self.attackTimer = self.attackCD
    end
end


function ParkourBoss:_PlayAnim(id)
    self.animator:SetInteger( act_id, id )
end



return ParkourBoss